import pathlib,json,hashlib,sys,re
root=pathlib.Path.cwd();name=sys.argv[1];assert name in ['emlf','mlfpkg'];manifest=root/'mlf-package.json';m=json.loads(manifest.read_text());t=m['executables'][name];assert not t.get('modules');assert not m.get('library');assert not t.get('no-prelude',False)
shared=json.loads((root/'shared-sources.json').read_text());source=root/t['main'];matches=[x for x in shared['modules'] if x['path']==t['main']];assert len(matches)==1;entry=matches[0]['module'];assert re.search(r'\bmodule\s+'+re.escape(entry)+r'\s+where\s*\{',source.read_text())
known={'mlf-foundation':'recovery-foundation-crate-O2-metadata-fix','mlf-language-core':'recovery-language-core-crate-O2','mlf-frontend':'recovery-frontend-crate-O2'}
for x in ['xmlf','inference','async','interpreter','llvm','crates','package-core','developer-tools']:known['mlf-'+x]='integration-modular/'+x
