deps=[str(root/'.mlf-build'/known[n]/'artifact/unit.mlfci') for n in sorted(t['dependencies'])];out=root/'.mlf-build/integration-modular'/('target-'+name);out.mkdir(exist_ok=True);pack=lambda xs:''.join(str(len(x))+':'+x for x in xs);fields=['MLF-CRATE-1',m['name']+'/'+m['version']+'/target-'+name,entry,'false',pack([pack([entry,str(source)])]),pack(deps),str(out/'queries'),str(root/'.mlf-build/recovery-foundation-crate-O2-metadata-fix/builtin/unit')]
(out/'queries').mkdir(exist_ok=True);(out/'artifact').mkdir(exist_ok=True);(out/'crate.spec').write_text(pack(fields));(out/'spec-fields.json').write_text(json.dumps(fields,indent=2)+'\n');cmd=[str(root/'.mlf-build/recovery-ghc-O2/bin/emlf'),'--compile-crate',str(out/'crate.spec'),'-o',str(out/'artifact/unit')];(out/'command.json').write_text(json.dumps(cmd,indent=2)+'\n');(out/'run.py').write_text('import subprocess,json\nfrom pathlib import Path\nsubprocess.run(json.loads((Path(__file__).parent/"command.json").read_text()),check=True)\n')
paths=[manifest,source,root/'shared-sources.json',*[pathlib.Path(p) for p in deps],*[pathlib.Path(p).with_suffix('.mlfco') for p in deps],root/'.mlf-build/recovery-ghc-O2/receipt.json',out/'crate.spec'];hashes={str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths};(out/'inputs.before.json').write_text(json.dumps(hashes,indent=2)+'\n');print(json.dumps({'entry':entry,'dependencies':sorted(t['dependencies']),'spec_sha256':hashes[str(out/'crate.spec')]}))
